def transform(grid):
    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    pts=[(r,c) for r in range(h) for c in range(w) if grid[r][c] not in (3,6)]
    for r,c in pts:
        color=grid[r][c]
        for y in range(h):
            if grid[y][c]==3: out[y][c]=color
        out[r][c]=4
    return out
